def transform(grid):
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for color in set(cnt)-{bg}:
        pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==color}
        rowends=set()
        for r in range(h):
            cs=[c for rr,c in pts if rr==r]
            if len(cs)>=2:
                rowends.add(min(cs)); rowends.add(max(cs))
            if len(cs)>=3:
                for c in range(min(cs),max(cs)+1):
                    if out[r][c]==bg: out[r][c]=2
        colrows={c:sorted(r for r,cc in pts if cc==c) for c in range(w)}
        # Rectangle sides are columns that occur as ends of horizontal strokes.
        for c1 in sorted(rowends):
            for c2 in sorted(rowends):
                if c1>=c2 or len(colrows[c1])<2 or len(colrows[c2])<2: continue
                r1=max(colrows[c1][0],colrows[c2][0])
                r2=min(colrows[c1][-1],colrows[c2][-1])
                if r1>=r2 or not all((r,c) in pts for r,c in ((r1,c1),(r1,c2),(r2,c1),(r2,c2))): continue
                for c in range(c1,c2+1):
                    if out[r1][c]==bg: out[r1][c]=2
                    if out[r2][c]==bg: out[r2][c]=2
                for r in range(r1,r2+1):
                    if out[r][c1]==bg: out[r][c1]=2
                    if out[r][c2]==bg: out[r][c2]=2
    return out
